// A minimal XML reader for tests: builds a tree {name, attrs, children, text} and throws on any
// well-formedness error (unbalanced or mismatched tags, '<' in text, an unterminated tag).
// Enough for OOXML parts generated by export-core.js; not a general XML parser.
function parseXml(source) {
  const src = String(source);
  const root = { name: '#document', attrs: {}, children: [], text: '' };
  const stack = [root];
  const tagRe = /<(\/?)([A-Za-z_][\w:.-]*)((?:\s+[\w:.-]+="[^"]*")*)\s*(\/?)>|<\?[\s\S]*?\?>/y;
  let i = 0;
  while (i < src.length) {
    const lt = src.indexOf('<', i);
    const textEnd = lt < 0 ? src.length : lt;
    const text = src.slice(i, textEnd);
    if (text) {
      if (text.includes('>')) throw new Error('unescaped ">" in text near ' + i);
      if (/&(?!(?:amp|lt|gt|quot|apos|#\d+|#x[0-9a-fA-F]+);)/.test(text)) throw new Error('unescaped "&" in text near ' + i);
      stack[stack.length - 1].text += text.replace(/&(amp|lt|gt|quot|apos);/g, (m, e) => ({ amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" }[e]));
    }
    if (lt < 0) break;
    tagRe.lastIndex = lt;
    const m = tagRe.exec(src);
    if (!m) throw new Error('bad tag at ' + lt + ': ' + src.slice(lt, lt + 40));
    i = tagRe.lastIndex;
    if (m[2] === undefined) continue;   // <?xml ... ?>
    const top = stack[stack.length - 1];
    if (m[1]) {
      if (top.name !== m[2]) throw new Error(`mismatched </${m[2]}> closes <${top.name}>`);
      stack.pop();
    } else {
      const attrs = {};
      for (const a of m[3].matchAll(/([\w:.-]+)="([^"]*)"/g)) {
        if (a[1] in attrs) throw new Error('duplicate attribute ' + a[1]);
        attrs[a[1]] = a[2];
      }
      const node = { name: m[2], attrs, children: [], text: '' };
      top.children.push(node);
      if (!m[4]) stack.push(node);
    }
  }
  if (stack.length !== 1) throw new Error('unclosed <' + stack[stack.length - 1].name + '>');
  if (root.children.length !== 1) throw new Error('expected exactly one root element');
  return root.children[0];
}

const find = (node, name, out = []) => {
  if (node.name === name) out.push(node);
  node.children.forEach((c) => find(c, name, out));
  return out;
};
const child = (node, name) => node.children.find((c) => c.name === name);
const textOf = (node) => node.text + node.children.map(textOf).join('');

module.exports = { parseXml, find, child, textOf };
